package com.bank.rotation;

import java.util.logging.Logger;

// Decides whether two circular reference codes are rotations for National Bank of India.
public class RotationChecker {
    private static final Logger log = Logger.getLogger(RotationChecker.class.getName());

    // Rotation check: equal length AND b is a substring of a+a. O(n) with KMP.
    public boolean areRotations(String a, String b) {
        if (a == null || b == null) {
            throw new IllegalArgumentException("inputs must not be null");
        }
        if (a.length() != b.length()) {        // mandatory length guard
            log.info(() -> "'" + a + "' / '" + b + "' → different length, not rotations");
            return false;
        }
        String doubled = a + a;                 // contains every rotation of a
        boolean rotated = doubled.contains(b);  // use KMP for strict O(n)
        log.info(() -> "'" + a + "' / '" + b + "' → " + (rotated ? "rotations" : "not rotations"));
        return rotated;
    }
}
