package com.bank.rotation;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: compare circular reference codes for rotation.
public class RotationCheckerDemo {
    private static final Logger log = Logger.getLogger(RotationCheckerDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        RotationChecker checker = new RotationChecker();

        log.info(() -> "Result = " + checker.areRotations("ABCDE", "CDEAB")); // true
        log.info(() -> "Result = " + checker.areRotations("ABCDE", "ABCED")); // false
        log.info(() -> "Result = " + checker.areRotations("AB", "ABC"));      // false (len)
    }
}
